  "concept_sources": {
    "standard_mandates": [
      {
        "source": "Not Specified",
        "clause": "Not Specified",
        "content": "Context中未包含《科学技术馆建设标准》或《博物馆建筑设计规范》等规范的原文条款，仅提供了新疆、厦门、北京、山西四地科技馆的案例描述。"
      },
      {
        "source": "Not Specified",
